import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const SCHEMA_PATH = resolve(root, "protocol/plugin-api.v1.json");
export const OUTPUT_PATH = resolve(root, "packages/protocol/src/generated.ts");

const HEADER =
  "// Generated by scripts/generate-protocol.mjs from protocol/plugin-api.v1.json. Do not edit.\n";

const literal = (value) => JSON.stringify(value);
const paren = (type) => (/[|&]/.test(type) ? `(${type})` : type);

function primitive(name) {
  if (name === "integer" || name === "number") return "number";
  if (name === "string" || name === "boolean" || name === "null") return name;
  throw new Error(`unsupported schema type ${name}`);
}

function ts(schema) {
  if (schema.$ref) return schema.$ref.split("/").at(-1);
  if ("const" in schema) return literal(schema.const);
  if (schema.enum) return schema.enum.map(literal).join(" | ");
  if (schema.oneOf) return schema.oneOf.map((member) => ts(member)).join(" | ");
  if (Array.isArray(schema.type)) return schema.type.map(primitive).join(" | ");
  switch (schema.type) {
    case "array":
      return `${paren(ts(schema.items ?? {}))}[]`;
    case "object":
      return objectType(schema);
    case undefined:
      return "unknown";
    default:
      return primitive(schema.type);
  }
}

function objectType(schema) {
  const props = schema.properties;
  const extra = schema.additionalProperties;
  if (!props || Object.keys(props).length === 0) {
    if (extra && typeof extra === "object") return `Record<string, ${ts(extra)}>`;
    return schema.additionalProperties === false
      ? "Record<string, never>"
      : "Record<string, unknown>";
  }
  const required = new Set(schema.required ?? []);
  const members = Object.entries(props).map(
    ([name, child]) => `${literal(name)}${required.has(name) ? "" : "?"}: ${ts(child)}`,
  );
  return `{ ${members.join("; ")} }`;
}

const section = (title, entries) => `export interface ${title} {\n${entries.join("\n")}\n}\n`;

export function generate(schema) {
  const out = [HEADER];
  out.push(`export const API_VERSION = ${schema.apiVersion} as const;\n`);
  out.push(`export const ERROR_CODES = ${JSON.stringify(schema.errorCodes)} as const;`);
  out.push("export type ErrorCode = (typeof ERROR_CODES)[number];\n");
  out.push(`export type Capability = ${schema.capabilities.map(literal).join(" | ")};\n`);
  for (const [name, def] of Object.entries(schema.$defs)) {
    out.push(`export type ${name} = ${ts(def)};\n`);
  }
  const methods = Object.entries(schema.methods);
  out.push(
    section(
      "MethodMap",
      methods.map(
        ([name, def]) =>
          `  ${literal(name)}: { params: ${ts(def.params)}; result: ${ts(def.result)} };`,
      ),
    ),
  );
  out.push("export type MethodName = keyof MethodMap;\n");
  out.push(
    `export const METHOD_CAPABILITY: Record<MethodName, Capability> = {\n${methods
      .map(([name, def]) => `  ${literal(name)}: ${literal(def.capability)},`)
      .join("\n")}\n};\n`,
  );
  const callbacks = Object.entries(schema.callbacks);
  out.push(
    section(
      "CallbackMap",
      callbacks.map(
        ([name, def]) =>
          `  ${literal(name)}: { params: ${ts(def.params)}; result: ${ts(def.result)} };`,
      ),
    ),
  );
  out.push("export type CallbackName = keyof CallbackMap;\n");
  const events = Object.entries(schema.events);
  out.push(
    section(
      "EventMap",
      events.map(([name, def]) => `  ${literal(name)}: ${ts(def.payload)};`),
    ),
  );
  out.push("export type EventName = keyof EventMap;\n");
  out.push(
    `export const EVENT_CAPABILITY: Record<EventName, Capability> = {\n${events
      .map(([name, def]) => `  ${literal(name)}: ${literal(def.capability)},`)
      .join("\n")}\n};\n`,
  );
  return out.join("\n");
}

export function render() {
  return generate(JSON.parse(readFileSync(SCHEMA_PATH, "utf8")));
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = render();
  if (process.argv.includes("--check")) {
    const current = readFileSync(OUTPUT_PATH, "utf8");
    if (current !== next) {
      process.stderr.write(
        "packages/protocol/src/generated.ts is out of date with protocol/plugin-api.v1.json, run: bun run protocol:generate\n",
      );
      process.exit(1);
    }
  } else {
    writeFileSync(OUTPUT_PATH, next);
  }
}
